island-perimeter:
class Solution:
    def islandPerimeter(self, grid: List[List[int]]) -> int:
        p = 0
        for i in range(len(grid)):
            for j in range(len(grid[0])):
                if grid[i][j]:
                    p += 4 - sum([i > 0 and grid[i-1][j], j > 0 and grid[i][j-1]])
        return p

