license-key-formatting:
class Solution:
    def licenseKeyFormatting(self, s: str, k: int) -> str:
        t = s.replace('-', '').upper()
        first = len(t) % k
        parts = ([t[:first]] if first else []) + [t[i:i+k] for i in range(first, len(t), k)]
        return '-'.join(parts)

relative-ranks:
class Solution:
    def findRelativeRanks(self, score: List[int]) -> List[str]:
        order = sorted(range(len(score)), key=lambda i: -score[i])
        res = [''] * len(score)
        for rank, i in enumerate(order):
            res[i] = ['Gold Medal', 'Silver Medal', 'Bronze Medal'][rank] if rank < 3 else str(rank + 1)
        return res

perfect-number:
class Solution:
    def checkPerfectNumber(self, num: int) -> bool:
        if num <= 1: return False
        s = 1
        i = 2
        while i * i <= num:
            if num % i == 0:
                s += i + (num // i if i != num // i else 0)
            i += 1
        return s == num

