flood-fill:
class Solution:
    def floodFill(self, image: List[List[int]], sr: int, sc: int, color: int) -> List[List[int]]:
        old = image[sr][sc]
        if old == color: return image
        stack = [(sr, sc)]
        while stack:
            i, j = stack.pop()
            if 0 <= i < len(image) and 0 <= j < len(image[0]) and image[i][j] == old:
                image[i][j] = color
                stack += [(i+1,j),(i-1,j),(i,j+1),(i,j-1)]
        return image

